/*
 * MANUAL FILE (not generated by HARIA). Safe across regenerations.
 *
 * Comportamiento de cliente de las páginas WikiGames (antes en WikiGames.HTML/js/common.js).
 * Los datos ya NO vienen de data.js: el servidor (Razor) pinta el HTML y este script solo
 * añade iconos, avisos y la interacción de los formularios. Toda acción persistente se envía
 * al servidor mediante <form method="post"> con antiforgery.
 */
(function () {
  const icon = (paths, cls = "icon") =>
    `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;

  const STAR = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.5l2.9 6 6.6.9-4.8 4.6 1.2 6.5L12 17.4l-5.9 3.1 1.2-6.5L2.5 9.4l6.6-.9z"/></svg>';

  const ICONS = {
    logo: `<svg class="logo" viewBox="0 0 32 32" aria-hidden="true"><rect x="1" y="1" width="30" height="30" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M9 13h4m-2-2v4M20 12.5h.01M23 15.5h.01" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/><path d="M8.5 9.5h15a3 3 0 0 1 3 3.2l-.6 7.3a2.5 2.5 0 0 1-4.3 1.5L19 19h-6l-2.6 2.5a2.5 2.5 0 0 1-4.3-1.5l-.6-7.3a3 3 0 0 1 3-3.2z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>`,
    settings: icon('<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>'),
    login: icon('<path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/><path d="M10 17l5-5-5-5"/><path d="M15 12H3"/>'),
    logout: icon('<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="M16 17l5-5-5-5"/><path d="M21 12H9"/>'),
    search: icon('<circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/>'),
    user: icon('<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>'),
    users: icon('<circle cx="9" cy="8" r="4"/><path d="M1 21a8 8 0 0 1 16 0"/><path d="M17 4a4 4 0 0 1 0 8M23 21a8 8 0 0 0-5-7.4"/>'),
    plus: icon('<path d="M12 5v14M5 12h14"/>'),
    heart: icon('<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8l1 1.1L12 21l7.8-7.5 1-1.1a5.5 5.5 0 0 0 0-7.8z"/>'),
    trash: icon('<path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>'),
    check: icon('<path d="M20 6L9 17l-5-5"/>'),
    x: icon('<path d="M18 6L6 18M6 6l12 12"/>'),
    flag: icon('<path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><path d="M4 22v-7"/>'),
    bell: icon('<path d="M18 8a6 6 0 0 0-12 0c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/>'),
    gamepad: icon('<path d="M6 11h4M8 9v4M15 12h.01M18 10h.01"/><rect x="2" y="6" width="20" height="12" rx="4"/>'),
    image: icon('<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/>'),
    back: icon('<path d="M15 18l-6-6 6-6"/>'),
    star: STAR,
  };

  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  function paintIcons(root = document) {
    root.querySelectorAll("[data-icon]").forEach((n) => (n.innerHTML = ICONS[n.dataset.icon] || ""));
  }

  function toast(msg) {
    let t = document.querySelector(".toast");
    if (!t) {
      t = document.createElement("div");
      t.className = "toast";
      t.setAttribute("role", "status");
      document.body.appendChild(t);
    }
    t.textContent = msg;
    t.classList.add("show");
    clearTimeout(t._h);
    t._h = setTimeout(() => t.classList.remove("show"), 2600);
  }

  /** Lee un bloque <script type="application/json" id="..."> pintado por Razor. */
  function readJson(id, fallback) {
    const el = document.getElementById(id);
    if (!el) return fallback;
    try { return JSON.parse(el.textContent); } catch { return fallback; }
  }

  /**
   * Modal de confirmación con el estilo de la web (sustituye a window.confirm).
   * Devuelve una Promise<boolean>. Esc o clic fuera = cancelar.
   */
  function confirmModal({ title = "Confirmar acción", message = "", ok = "Confirmar", cancel = "Cancelar", variant = "danger", icon } = {}) {
    let dlg = document.getElementById("wg-confirm");
    if (!dlg) {
      dlg = document.createElement("dialog");
      dlg.id = "wg-confirm";
      dlg.className = "modal card";
      dlg.setAttribute("aria-labelledby", "wg-confirm-title");
      dlg.setAttribute("aria-describedby", "wg-confirm-msg");
      dlg.innerHTML = `
        <form method="dialog" class="modal-body">
          <div class="modal-head">
            <span class="modal-icon" aria-hidden="true"></span>
            <h3 id="wg-confirm-title"></h3>
          </div>
          <p id="wg-confirm-msg" class="modal-msg"></p>
          <div class="modal-actions">
            <button type="submit" value="cancel" class="btn btn-ghost" data-role="cancel"></button>
            <button type="submit" value="ok" class="btn" data-role="ok"></button>
          </div>
        </form>`;
      // Clic en el fondo (fuera de la caja) cierra como cancelar.
      dlg.addEventListener("click", (e) => { if (e.target === dlg) dlg.close("cancel"); });
      document.body.appendChild(dlg);
    }
    const iconName = icon || (variant === "danger" ? "trash" : "check");
    dlg.querySelector(".modal-icon").innerHTML = ICONS[iconName] || "";
    dlg.querySelector("#wg-confirm-title").textContent = title;
    dlg.querySelector("#wg-confirm-msg").textContent = message;
    dlg.querySelector('[data-role="cancel"]').textContent = cancel;
    const okBtn = dlg.querySelector('[data-role="ok"]');
    okBtn.textContent = ok;
    okBtn.className = "btn " + (variant === "danger" ? "btn-danger" : "btn-primary");
    dlg.dataset.variant = variant;

    return new Promise((resolve) => {
      dlg.returnValue = "cancel";
      dlg.addEventListener("close", () => resolve(dlg.returnValue === "ok"), { once: true });
      dlg.showModal();
      dlg.querySelector('[data-role="cancel"]').focus();
    });
  }

  window.UI = { ICONS, STAR, esc, toast, paintIcons, readJson, confirm: confirmModal };

  document.addEventListener("DOMContentLoaded", () => {
    paintIcons();

    // Aviso enviado por el servidor tras un POST (TempData["Toast"]).
    if (document.body.dataset.toast) toast(document.body.dataset.toast);

    // <select data-autosubmit>: envía su formulario al cambiar (filtros, rol, estado…).
    document.querySelectorAll("[data-autosubmit]").forEach((el) =>
      el.addEventListener("change", () => el.form && el.form.requestSubmit()));

    // <form data-confirm="..."> pide confirmación (modal propio) antes de enviarse.
    // Opcionales: data-confirm-title, data-confirm-ok (texto del botón), data-confirm-variant="danger|primary".
    document.querySelectorAll("form[data-confirm]").forEach((f) =>
      f.addEventListener("submit", (e) => {
        if (f._confirmed) { f._confirmed = false; return; }
        e.preventDefault();
        const submitter = e.submitter;
        confirmModal({
          title: f.dataset.confirmTitle || "Confirmar acción",
          message: f.dataset.confirm,
          ok: f.dataset.confirmOk || "Confirmar",
          variant: f.dataset.confirmVariant || "danger",
          icon: f.dataset.confirmIcon,
        }).then((ok) => {
          if (!ok) return;
          f._confirmed = true;
          f.requestSubmit(submitter && submitter.form === f ? submitter : undefined);
        });
      }));

    // Tarjetas clicables (denuncias): navegan a data-href salvo si se pulsa un control.
    document.querySelectorAll("[data-href]").forEach((card) => {
      const go = () => card.dataset.href && (location.href = card.dataset.href);
      card.addEventListener("click", (e) => { if (!e.target.closest("a, button, select, form")) go(); });
      card.addEventListener("keydown", (e) => { if (e.key === "Enter" && e.target === card) go(); });
    });
  });
})();
